    var d = typeof result === 'string' ? JSON.parse(result) : result;
    var vod = (d && d.list) ? d.list[0] : {};
    var playFrom = (vod.vod_play_from || '').split('$$$');
    var playUrl = (vod.vod_play_url || '').split('$$$');
    for (var i = 0; i < playUrl.length; i++) {
      if (!playUrl[i]) continue;
      var lineName = (playFrom[i] || '线路' + (i+1)).trim();
      var episodes = playUrl[i].split('#');
      for (var j = 0; j < episodes.length; j++) {
        if (!episodes[j]) continue;
        var parts = episodes[j].split('$');
        // 核心修复点：无视垃圾站的数据缺失，强吃裸链
        if (parts.length > 1) {
          list.push({ name: lineName + ' - ' + parts[0], url: parts[1] });
        } else {
          var epName = episodes.length > 1 ? ('第' + (j+1) + '集') : '播放';
          list.push({ name: lineName + ' - ' + epName, url: parts[0] });
        }
      }
    }
