				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});
push("全部🌊分类",null,1,1)
	arList=["言情","总裁","都市","穿越","仙侠","武侠","恐怖","悬疑","耽美","玄幻"]
